(() => {
 const style=document.createElement('style');style.textContent=`.experiences{padding:76px 0;background:var(--cream)}.experience-head{max-width:720px;margin-bottom:28px}.experience-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.experience{background:var(--white);border:1px solid var(--line);border-radius:16px;overflow:hidden}.experience img{width:100%;height:180px;object-fit:cover;display:block}.experience div{padding:15px}.experience h3{margin:0 0 6px;font-size:19px}.experience p{font-size:14px;color:var(--muted);margin:0}@media(max-width:900px){.experience-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:550px){.experience-grid{grid-template-columns:1fr}.experience img{height:210px}}`;document.head.append(style);
 const target=document.querySelector('#eventos');if(!target)return;const section=document.createElement('section');section.className='experiences';section.id='experiencias-reales';section.innerHTML=`<div class="shell"><div class="experience-head"><div class="eyebrow">Más que alojamiento</div><h2>Experiencias para recordar</h2><p>Una selección de espacios y actividades reales del Fundo El Grillo: naturaleza, descanso y tiempo compartido.</p></div><div class="experience-grid"><article class="experience"><img loading="lazy" decoding="async" src="/assets/nosotros/1.jpg" alt="Granja educativa"><div><h3>Granja educativa</h3><p>Un encuentro cercano con animales de granja para disfrutar en familia.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/nosotros/4.jpg" alt="Jardines del fundo"><div><h3>Jardines y áreas verdes</h3><p>Rincones para descansar, caminar y conectar con el entorno.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/nosotros/8.jpg" alt="Paisajes del Fundo El Grillo"><div><h3>Senderos y vistas</h3><p>Rutas de caminata por la Quebrada del Ají y bosque nativo.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/nosotros/11.jpg" alt="Naturaleza del Fundo El Grillo"><div><h3>Productos del fundo</h3><p>Frutas, miel y aceite de oliva cultivados en este entorno.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/salones/1.jpg" alt="Salón Darwin"><div><h3>Salón Darwin</h3><p>Espacio para matrimonios, ceremonias y celebraciones de hasta 250 personas.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/salones/6.jpg" alt="Salón Orgánico"><div><h3>Salón Orgánico</h3><p>Terraza, áreas verdes y piscina para encuentros especiales.</p></div></article><article class="experience"><img loading="lazy" decoding="async" src="/assets/salones/10.jpg" alt="Quincho Club House"><div><h3>Quincho Club House</h3><p>Salón y quincho para compartir al aire libre.</p></div></article></div></div>`;target.before(section);
})();
